(function () {
  'use strict';

  const SELECTORS = {
    component: '[data-cmp-is="grid-container"]',
    wrapper: '.cmp-grid-container-wrapper',
    moreLink: '.cmp-grid-container__more'
  };

  const DATA_ATTRS = {
    // Spacing shorthand (wrapper)
    margin: 'margin',
    padding: 'padding',
    mobileMargin: 'mobileMargin',
    mobilePadding: 'mobilePadding',
    // Content specific (grid)
    contentPadding: 'contentPadding',
    contentMaxWidth: 'contentMaxWidth',
    contentCentered: 'contentCentered',
    mobileContentPadding: 'mobileContentPadding'
  };

  function normalizeToSlug(text) {
    if (!text) return '';
    return text
      .toString()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');
  }

  function cleanValue(value) {
    if (!value) return '';
    return value.replace(/^[,\s]+|[,\s]+$/g, '').trim();
  }

  function getUserSegment() {
    if (window.dataLayer && window.dataLayer.length > 0) {
      for (let i = window.dataLayer.length - 1; i >= 0; i--) {
        if (window.dataLayer[i].user && window.dataLayer[i].user.segment) {
          return window.dataLayer[i].user.segment;
        }
      }
    }

    const headerFooterScript = document.querySelector('script[src*="header-footer"]');
    if (headerFooterScript) {
      const scriptSrc = headerFooterScript.getAttribute('src');
      if (scriptSrc) {
        const typeMatch = scriptSrc.match(/[?&]type=([^&]+)/);
        if (typeMatch && typeMatch[1]) {
          return typeMatch[1];
        }
      }
    }

    const urlPath = window.location.pathname.toLowerCase();
    if (urlPath.includes('/exclusive/')) return 'exclusive';
    if (urlPath.includes('/prime/')) return 'prime';
    if (urlPath.includes('/next/')) return 'next';

    return 'classic';
  }

  function getLoginStatus() {
    if (window.dataLayer && window.dataLayer.length > 0) {
      for (let i = window.dataLayer.length - 1; i >= 0; i--) {
        if (window.dataLayer[i].user && window.dataLayer[i].user.logged_user) {
          return window.dataLayer[i].user.logged_user;
        }
      }
    }

    const loginIndicators = document.querySelectorAll('.logged-in, [data-logged="true"], .user-logged');
    if (loginIndicators.length > 0) return 'logado';
    if (document.cookie.includes('logged') || localStorage.getItem('logged')) return 'logado';

    return 'deslogado';
  }

  function getGTMConfig(element) {
    return {
      location: cleanValue(element.getAttribute('data-gtm-location')) || 'grid-container',
      action: cleanValue(element.getAttribute('data-gtm-action')) || 'clique-botao',
      product: cleanValue(element.getAttribute('data-gtm-product')) || 'portal-bradesco',
      flow: cleanValue(element.getAttribute('data-gtm-flow')) || '',
      segment: cleanValue(element.getAttribute('data-gtm-segment')) || '',
      loggedUser: cleanValue(element.getAttribute('data-gtm-logged-user')) || ''
    };
  }

  function trackEvent(elementName, component) {
    try {
      if (typeof window.dataLayer === 'undefined') {
        window.dataLayer = [];
      }

      const gtmConfig = getGTMConfig(component);
      const elementSlug = normalizeToSlug(elementName || 'grid-container');
      const segmentoConta = gtmConfig.segment || getUserSegment();
      const statusLogin = gtmConfig.loggedUser || getLoginStatus();

      const eventData = {
        event: 'Event_Data',
        event_type: 'new',
        ga_event: {
          location: gtmConfig.location,
          action: gtmConfig.action,
          element_name: elementSlug
        },
        product: {
          product: gtmConfig.product,
          flow: gtmConfig.flow
        },
        user: {
          segment: segmentoConta,
          logged_user: statusLogin
        }
      };

      window.dataLayer.push(eventData);
    } catch (error) {
      console.error('Erro ao enviar evento GTM para Grid Container:', error);
    }
  }

  /**
   * Parse shorthand spacing value (like CSS)
   * Supports: "10" | "10 20" | "10 20 30" | "10 20 30 40"
   * Returns: { top, right, bottom, left }
   */
  function parseSpacing(value) {
    if (!value || value.trim() === '') {
      return null;
    }

    const parts = value.trim().split(/\s+/).map(v => parseInt(v, 10));

    if (parts.some(isNaN)) {
      return null;
    }

    switch (parts.length) {
      case 1:
        return { top: parts[0], right: parts[0], bottom: parts[0], left: parts[0] };
      case 2:
        return { top: parts[0], right: parts[1], bottom: parts[0], left: parts[1] };
      case 3:
        return { top: parts[0], right: parts[1], bottom: parts[2], left: parts[1] };
      case 4:
        return { top: parts[0], right: parts[1], bottom: parts[2], left: parts[3] };
      default:
        return null;
    }
  }

  /**
   * GridContainer
   * Grid layout é controlado via classes CSS utilitárias
   * JavaScript aplica apenas margin, padding e maxWidth que são valores dinâmicos
   */
  class GridContainer {
    constructor(element) {
      this.element = element;
      this.wrapper = element.closest(SELECTORS.wrapper);
      this.config = this.getConfig();
      this.init();
    }

    getConfig() {
      const dataset = this.element.dataset;
      const wrapperDataset = this.wrapper ? this.wrapper.dataset : {};

      return {
        // Spacing shorthand from wrapper
        margin: parseSpacing(wrapperDataset[DATA_ATTRS.margin]),
        padding: parseSpacing(wrapperDataset[DATA_ATTRS.padding]),
        mobileMargin: parseSpacing(wrapperDataset[DATA_ATTRS.mobileMargin]),
        mobilePadding: parseSpacing(wrapperDataset[DATA_ATTRS.mobilePadding]),
        // Content specific
        contentPadding: parseSpacing(dataset[DATA_ATTRS.contentPadding]),
        mobileContentPadding: parseSpacing(dataset[DATA_ATTRS.mobileContentPadding]),
        contentMaxWidth: dataset[DATA_ATTRS.contentMaxWidth] || null,
        contentCentered: dataset[DATA_ATTRS.contentCentered] === 'true'
      };
    }

    init() {
      this.applyContentStyles();
      this.applyWrapperStyles();
      this.applyMobileStyles();
      this.bindGTMEvents();

      // Inicializar slider se habilitado
      if (this.element.dataset.enableSlider === 'true') {
        this.initSlider();
      }
    }

    bindGTMEvents() {
      if (!this.wrapper) {
        return;
      }

      const hasPointerEvents = typeof window.PointerEvent !== 'undefined';

      const handleTrack = (event) => {
        // When pointer events are available, pointerdown handles mouse/touch.
        // Keep click tracking only for keyboard activation (event.detail === 0).
        if (hasPointerEvents && event.type === 'click' && event.detail > 0) {
          return;
        }

        const link = event.target.closest(SELECTORS.moreLink);
        if (!link || !this.wrapper.contains(link)) {
          return;
        }

        const elementName = (link.textContent || 'ver-mais').trim();
        trackEvent(elementName, this.element);
      };

      if (hasPointerEvents) {
        this.wrapper.addEventListener('pointerdown', handleTrack);
      }
      this.wrapper.addEventListener('click', handleTrack);
    }

    initSlider() {
      let isDown = false;
      let startX;
      let scrollLeft;

      // Mouse drag to scroll
      this.element.addEventListener('mousedown', (e) => {
        // Ignora se clicou em um link ou botão
        if (e.target.closest('a, button')) {
          return;
        }

        isDown = true;
        this.element.classList.add('dragging');
        startX = e.pageX - this.element.offsetLeft;
        scrollLeft = this.element.scrollLeft;
        e.preventDefault();
      });

      this.element.addEventListener('mouseleave', () => {
        isDown = false;
        this.element.classList.remove('dragging');
      });

      this.element.addEventListener('mouseup', () => {
        isDown = false;
        this.element.classList.remove('dragging');
      });

      this.element.addEventListener('mousemove', (e) => {
        if (!isDown) return;
        e.preventDefault();
        const x = e.pageX - this.element.offsetLeft;
        const walk = (x - startX) * 2; // Multiplicador para velocidade
        this.element.scrollLeft = scrollLeft - walk;
      });

      // Touch scroll é nativo, mas podemos adicionar algum feedback
      this.element.addEventListener('touchstart', () => {
        this.element.classList.add('dragging');
      }, { passive: true });

      this.element.addEventListener('touchend', () => {
        this.element.classList.remove('dragging');
      }, { passive: true });
    }

    applyContentStyles() {
      const styles = {};

      // Content padding (padding interno do grid)
      if (this.config.contentPadding) {
        styles.paddingTop = `${this.config.contentPadding.top}px`;
        styles.paddingRight = `${this.config.contentPadding.right}px`;
        styles.paddingBottom = `${this.config.contentPadding.bottom}px`;
        styles.paddingLeft = `${this.config.contentPadding.left}px`;
      }

      // Content max width
      if (this.config.contentMaxWidth && this.config.contentMaxWidth !== 'none') {
        let maxWidth = this.config.contentMaxWidth;
        if (/^\d+$/.test(maxWidth)) {
          maxWidth = `${maxWidth}px`;
        }
        styles.maxWidth = maxWidth;

        // Centralizar se habilitado
        if (this.config.contentCentered) {
          styles.marginLeft = 'auto';
          styles.marginRight = 'auto';
        }
      }

      Object.assign(this.element.style, styles);
    }

    applyWrapperStyles() {
      if (!this.wrapper) return;

      const wrapperStyles = {};

      // Margins (shorthand)
      if (this.config.margin) {
        wrapperStyles.marginTop = `${this.config.margin.top}px`;
        wrapperStyles.marginRight = `${this.config.margin.right}px`;
        wrapperStyles.marginBottom = `${this.config.margin.bottom}px`;
        wrapperStyles.marginLeft = `${this.config.margin.left}px`;
      }

      // Paddings (shorthand)
      if (this.config.padding) {
        wrapperStyles.paddingTop = `${this.config.padding.top}px`;
        wrapperStyles.paddingRight = `${this.config.padding.right}px`;
        wrapperStyles.paddingBottom = `${this.config.padding.bottom}px`;
        wrapperStyles.paddingLeft = `${this.config.padding.left}px`;
      }

      Object.assign(this.wrapper.style, wrapperStyles);
    }

    applyMobileStyles() {
      // Aplica estilos mobile via CSS custom properties
      // que serão usadas em media queries no CSS
      if (this.wrapper && this.config.mobileMargin) {
        this.wrapper.style.setProperty('--mobile-margin-top', `${this.config.mobileMargin.top}px`);
        this.wrapper.style.setProperty('--mobile-margin-right', `${this.config.mobileMargin.right}px`);
        this.wrapper.style.setProperty('--mobile-margin-bottom', `${this.config.mobileMargin.bottom}px`);
        this.wrapper.style.setProperty('--mobile-margin-left', `${this.config.mobileMargin.left}px`);
      }

      if (this.wrapper && this.config.mobilePadding) {
        this.wrapper.style.setProperty('--mobile-padding-top', `${this.config.mobilePadding.top}px`);
        this.wrapper.style.setProperty('--mobile-padding-right', `${this.config.mobilePadding.right}px`);
        this.wrapper.style.setProperty('--mobile-padding-bottom', `${this.config.mobilePadding.bottom}px`);
        this.wrapper.style.setProperty('--mobile-padding-left', `${this.config.mobilePadding.left}px`);
      }

      if (this.config.mobileContentPadding) {
        this.element.style.setProperty('--mobile-content-padding-top', `${this.config.mobileContentPadding.top}px`);
        this.element.style.setProperty('--mobile-content-padding-right', `${this.config.mobileContentPadding.right}px`);
        this.element.style.setProperty('--mobile-content-padding-bottom', `${this.config.mobileContentPadding.bottom}px`);
        this.element.style.setProperty('--mobile-content-padding-left', `${this.config.mobileContentPadding.left}px`);
      }
    }
  }

  function initGridContainers() {
    const containers = document.querySelectorAll(SELECTORS.component);
    containers.forEach(container => {
      if (!container.gridContainerInstance) {
        container.gridContainerInstance = new GridContainer(container);
      }
    });
  }

  // Initialize on DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initGridContainers);
  } else {
    initGridContainers();
  }

  // Re-initialize on mutations (for AEM author mode)
  if (typeof MutationObserver !== 'undefined') {
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.addedNodes.length) {
          initGridContainers();
        }
      });
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  // Expose for external use
  window.GridContainer = GridContainer;
  window.initGridContainers = initGridContainers;

})();
